"""Render the existing owner PNG as terminal half-block cells, without redrawing it."""

import argparse
import hashlib
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "launcher/assets/branding/icon.png"
OUTPUT = ROOT / "tui/src/ore_pixels.rs"


def generated():
    with Image.open(SOURCE) as image:
        pixels = image.convert("RGBA").resize((12, 14), Image.Resampling.NEAREST)
    rows = [
        "// Generated by scripts/tui_branding.py from the unchanged owner PNG.",
        "// SHA256: " + hashlib.sha256(SOURCE.read_bytes()).hexdigest(),
        "pub const ORE: [[u8; 4]; 168] = [",
    ]
    for y in range(14):
        for x in range(12):
            r, g, b, a = pixels.getpixel((x, y))
            rows.append(f"    [{r}, {g}, {b}, {a}],")
    return "\n".join([*rows, "];", ""])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = generated()
    if args.check:
        if OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit(
                "TUI ore differs from the owner PNG; run scripts/tui_branding.py"
            )
    else:
        OUTPUT.write_text(content, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
